//! WideBalance against vectors printed by the geth-XDC Go oracle
//! (spikes/wide-balance/oracle, regenerated by run.sh).

use alloy_primitives::U256;
use alloy_rlp::{Decodable, Encodable};
use proptest::prelude::*;
use serde::Deserialize;
use xone_primitives::{WideBalance, WideBalanceError, MAX_WIDE_BITS};

#[derive(Deserialize)]
struct Vector {
    name: String,
    r#true: String,
    low: String,
    is_wide: bool,
    balance_rlp: String,
}

fn vectors() -> Vec<Vector> {
    serde_json::from_str(include_str!("vectors/wide_balance.json")).unwrap()
}

fn hex(s: &str) -> Vec<u8> {
    let s = s.strip_prefix("0x").unwrap();
    let s = if s.len() % 2 == 1 {
        format!("0{s}")
    } else {
        s.to_string()
    };
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn enc(w: &WideBalance) -> Vec<u8> {
    let mut out = Vec::new();
    w.encode(&mut out);
    assert_eq!(out.len(), w.length());
    out
}

#[test]
fn matches_go_oracle() {
    let vs = vectors();
    assert_eq!(vs.len(), 8);
    for v in vs {
        let w = WideBalance::from_be_bytes(&hex(&v.r#true));
        assert_eq!(enc(&w), hex(&v.balance_rlp), "rlp {}", v.name);
        assert_eq!(w.low(), U256::from_be_slice(&hex(&v.low)), "low {}", v.name);
        assert_eq!(w.is_wide(), v.is_wide, "wide {}", v.name);
        let back = WideBalance::decode(&mut hex(&v.balance_rlp).as_slice()).unwrap();
        assert_eq!(back, w, "decode {}", v.name);
    }
}

/// The wrap rule is load-bearing: a saturating low part must disagree with Go.
#[test]
fn saturating_low_mutant_is_detected() {
    let mut detected = false;
    for v in vectors().iter().filter(|v| v.is_wide) {
        let w = WideBalance::from_be_bytes(&hex(&v.r#true));
        let mutant = U256::MAX;
        detected |= mutant != w.low() && w.low() == U256::from_be_slice(&hex(&v.low));
    }
    assert!(detected);
}

#[test]
fn arithmetic_and_bounds() {
    let max = WideBalance::from(U256::MAX);
    let wide = max.checked_add(U256::from(1)).unwrap();
    assert!(wide.is_wide() && wide.low().is_zero());
    assert_eq!(wide.checked_sub(U256::from(1)).unwrap(), max);
    assert_eq!(
        WideBalance::default().checked_sub(U256::from(1)),
        Err(WideBalanceError::Underflow)
    );
    // 2^264-1 is the last legal value; one more is a typed error, never a wrap.
    let top = WideBalance::from_be_bytes(&[0xff; 33]);
    assert!(top.check_legal().is_ok());
    assert_eq!(
        top.checked_add(U256::from(1)),
        Err(WideBalanceError::AboveBound)
    );
    assert_eq!(MAX_WIDE_BITS, 264);
}

#[test]
fn decode_rejects_non_canonical() {
    assert!(WideBalance::decode(&mut [0x82, 0x00, 0x01].as_slice()).is_err());
    assert!(WideBalance::decode(&mut [0x81, 0x01].as_slice()).is_err());
    assert!(WideBalance::decode(&mut [0xc0].as_slice()).is_err());
}

proptest! {
    #[test]
    fn round_trip_and_low(bytes in proptest::collection::vec(any::<u8>(), 0..=40)) {
        let w = WideBalance::from_be_bytes(&bytes);
        let back = WideBalance::decode(&mut enc(&w).as_slice()).unwrap();
        prop_assert_eq!(&back, &w);
        let be = w.to_be_bytes();
        let tail = &be[be.len().saturating_sub(32)..];
        prop_assert_eq!(w.low(), U256::from_be_slice(tail));
        prop_assert_eq!(w.is_wide(), be.len() > 32);
    }
}
